window.DOSIK=window.DOSIK||{};DOSIK["yc_group2"]={"1":[{"t":"tree","title":"집단상담의 이점","root":"집단상담의 이점","branches":[["사회장면","현실적이고 실제생활에 더 근접한 사회장면을 제공한다."],["이해와 수용","자신과 타인에 대한 이해와 수용의 폭이 넓어지는데 더 용이하다."],["지지와 보편성","나 혼자만의 문제가 아니라는 지지와 보편성을 획득하기가 더 쉽다."],["소속감","소속감이나 지원체계 및 동료의식을 발전시키기가 더 쉽다."]]},{"t":"def","term":"집단의 목표","text":"집단의 방향을 분명히 하는데 도움을 준다. · 집단 전체의 목표와 개인의 목표를 모두 설정하는 것이 필요하다.","ex":["집단 초기부터 집단원에게 명료하게 진술하고 이해시킬 필요가 있다.","집단상담의 효과와 평가를 위해 필수적이다."]},{"t":"vs","title":"치료집단과 참만남 집단","cols":[{"name":"치료집단","items":["심각한 정도의 정서ㆍ행동문제 또는 정신장애 치료를 목적으로 한다.","치료집단을 이끄는 사람을 집단치료자라고 한다.","공황장애 치료를 원하는 사람이 참가할 수 있다."]},{"name":"참만남 집단","items":["감수성 훈련을 위한 참만남 집단이 이에 속한다."]}]}],"2":[{"t":"table","title":"집단상담의 치료적 요인","head":["요인","내용"],"rows":[["원가족 재현","과거 가족과의 관계가 집단원이나 집단상담자에게 교정적으로 재연된다."],["정화","내적 감정의 개방적 표현을 통해 감정을 정화한다."],["실존","자신의 삶에 대한 궁극적 책임을 인식한다."],["모방","다른 집단원이나 집단상담자를 모델링한다."]]},{"t":"def","term":"대인관계 학습","text":"내가 다른 사람에게 어떤 모습으로 보이는지 알게 된다.","ex":["타인을 짜증나게 하는 나의 습관이나 태도를 알게 된다.","내 생각을 말하지 않음으로써 때때로 사람들을 혼란에 빠뜨린다는 점을 알게 된다.","내가 다른 사람에게 어떤 인상을 주는지 알게 된다."]}],"3":[{"t":"def","term":"집단역동","text":"집단원, 집단상담자, 집단 전체와의 관계를 포함한다."},{"t":"cause","title":"집단응집력","causes":["집단원들이 집단에 대해 느끼는 매력으로 집단에 남아 있도록 하는 힘이다."],"result":"다른 치료적 요인이 최상의 기능을 하도록 하기 위한 필수적인 선행 조건이다.","effects":["응집력이 높을수록 출석, 참여, 상호지지의 비율이 높다."]},{"t":"tree","title":"응집력이 높은 집단","root":"응집력이 높은 집단","branches":[["신뢰","집단원들이 서로 신뢰하고 기꺼이 위험을 감수한다."],["피드백","피드백이 자유롭게 오가며 거부감 없이 수용된다. · 무분별한 공격이 아닌 생산적인 피드백이 이루어진다."],["상호작용","지금-여기에서 의미 있는 상호작용이 이루어진다."],["참여","집단원은 집단 활동에 적극적으로 참여한다. · 자신의 개인적인 측면을 다른 집단원과 나눈다."],["지지와 도전","집단에서 다른 집단원을 지지하거나 그들에게 도전한다. · 집단의 안과 밖에서 위험을 감수한다."]]}],"4":[{"t":"vs","title":"초기단계 집단원","cols":[{"name":"집단원","items":["집단참여와 관련하여 두려움과 주저하는 태도를 보인다.","새로운 사람들과의 만남으로 인해 어색함을 느낀다.","집단에 대한 막연한 기대감을 가지기도 한다. · 집단에 대해 비합리적인 기대를 하기도 한다.","집단이 자기개방을 하기에 안전한 장소인지 탐색한다. · 자기표현을 하기에 안전한지 탐색한다.","불안과 긴장이 있기 때문에 의존적이고 소극적으로 행동하는 경향이 있다.","새로운 사람들과의 만남으로 자기개방에 부담을 느껴 집단 참여를 머뭇거린다."]},{"name":"집단상담자","items":["개방적이고 존중하는 태도로 집단원의 이야기를 듣고 집단원의 경험을 가치있게 여긴다.","집단원들의 두려움과 기대를 표현하도록 돕는다.","의존성을 부추기지 않으면서 집단원이 혼란스럽지 않도록 적당히 구조화한다.","집단과정을 신뢰하고 집단원들이 의미있는 변화를 만들어 내는 능력이 있음을 믿는다."]}]}],"5":[{"t":"flow","title":"집단발달단계","steps":["집단에 대한 소속감을 느낀다.","자기탐색과 변화에 대한 불안을 경험하고 방어적이 된다. · 집단상담자의 권위와 능력에 도전한다.","집단에서 배운 것을 도전하고 실천한다.","집단상담 전체과정을 평가하고 지속적 변화를 격려한다."]}],"6":[{"t":"table","title":"집단상담자의 역할","head":["역할","내용"],"rows":[["촉진자","집단원의 참여를 권장하고, 집단원이 자기이해와 자기탐구의 깊은 단계로 나아갈 수 있도록 돕는다."],["모범자","집단원이 새로운 행동변화를 시도할 수 있도록 분위기를 만들어 주고 집단 과정에서 본보기가 된다."],["참여적 관찰자","집단의 수용적이고 자율적 분위기 조성을 위해 집단원의 일원으로 참여하고 집단 전체의 상황을 주의 깊게 관찰한다."],["보호자","집단원들에게 권리와 책임에 대해 알려주고, 비밀보장의 중요성을 강조한다."]]}],"7":[{"t":"table","title":"개입기술","head":["기술","내용"],"rows":[["연결하기","집단원들 사이에 공감대를 형성한다. · 공통의 관심사에 주의를 기울이게 한다. · 집단원들 간의 보편성을 경험하게 한다."],["참여 촉진","집단원들의 참여를 촉진한다. · 집단의 상호작용을 촉진한다. · 집단의 응집력을 증가시킨다."],["보편성","집단원들이 자연스럽게 보편성을 경험하게 한다. · 집단원들이 서로의 유사성에 대해 알게 한다."]]},{"t":"def","term":"자기개방","text":"상담자도 한 인간이라는 것을 느낄 수 있도록 충분히 자신을 드러낸다.","ex":["상담자가 집단원에 의해 어떻게 영향을 받고 있는지를 적절하게 표현한다.","개방을 하나의 기법으로 사용하기보다는 적절하다고 판단될 때 자발적으로 해야 한다.","정직하고 적절하게 개방함으로써 집단원에게 집단규범 형성의 모델이 된다."]}],"8":[{"t":"table","title":"문제행동 대처","head":["문제행동","대처"],"rows":[["일반 탐색","집단원이 그 반응으로 어떤 잠재적 이익을 얻는지 탐색한다. · 집단원에 대한 집단상담자 자신의 반응을 검토해본다. · 집단원이 드러내는 감정이 집단 전체의 의견인지 확인해 본다. · 집단원의 전이 감정을 연상시키는 사람을 집단에서 찾아보도록 한다."],["침묵","생산적 침묵인지, 비생산적 침묵인지 검토한다. · 침묵이 집단원의 문화적 다양성에서 온 것은 아닌지 생각해 본다. · 침묵하는 집단원의 표정, 몸짓에 대해 언급함으로써 집단에 참여시킨다. · 생산적인 침묵이 생겨난 동안 어떤 집단원이 말하기 시작한 경우 조금 더 기다려 달라고 요청할 수 있다."],["적대적인 집단원","그 행동이 다른 집단원에게 미치는 영향에 대해 이야기하고, 원하는 것을 탐색하여 직접 표현하게 한다."],["지속적으로 침묵하는 집단원","다른 집단원이 자신의 침묵을 오해할 가능성도 있다는 것을 알려준다."],["질문공세를 하는 집단원","질문하기 전 마음속의 생각과 느낌에 대해 이야기하도록 요청 한다."],["사실적 이야기를 늘어놓는 집단원","그 경험에서 야기된 감정을 공감적 이해를 통해 현재형으로 표현하도록 한다."]]}],"9":[{"t":"tree","title":"정신분석적 집단상담","root":"정신분석적 집단상담","branches":[["핵심","치료의 핵심은 전이의 분석과 해결이다."],["기회","집단에서 과거를 재경험하여 무의식적 갈등을 해소할 수 있는 기회를 제공한다."],["목표","궁극적인 목표는 내담자의 신경증적 갈등을 경감시켜 인격적 성숙을 도모하는 것이다."]]},{"t":"vs","title":"집단상담자의 기능","cols":[{"name":"슬랩손(S. Slavson)","items":["집단상담자의 기능을 지도적 기능, 자극적 기능, 확충적 기능, 해석적 기능으로 구분한다."]},{"name":"볼프(A. Wolf)","items":["집단상담자가 자신을 향한 집단원들의 전이행동을 처리할 수 있어야 한다고 본다."]}]}],"10":[{"t":"tree","title":"아들러 집단상담의 관점","root":"아들러(개인심리학)","branches":[["행동","집단원의 행동은 유아기에 형성된 가족과의 · 사회적 상호작용 패턴을 드러낸다."],["인간","집단원은 누구나 불완전하고 열등감을 느끼는 존재라고 본다."],["열등감","집단원이 가진 열등감은 능력을 성취하기 위한 원동력으로서 · 우월성 추구로 발현된다고 본다."]]},{"t":"tree","title":"아들러 집단상담의 목표","root":"집단상담자의 조력","branches":[["재정향","집단원들이 바람직한 생활양식으로 재정향하도록 조력한다."],["생활양식","그릇된 생활양식을 변화시키도록 격려한다."],["이해","자기 행동의 목적과 결과에 대해 이해하도록 돕는다."],["지금-여기","집단원들의 지금-여기에서의 행동에 초점을 둔다."],["사회적 관심","집단원의 사회적 관심을 향상시키고자 한다."]]}],"11":[{"t":"def","term":"심리극","text":"억압된 감정을 표출하고 정화하여 통찰을 일으키도록 한다.","ex":["현실에서 일어날 수 없는 일까지 상상하게 하는 잉여현실을 도구로 활용한다.","과거 사건을 마치 지금 일어나는 것처럼 재연하게 한다."]},{"t":"flow","title":"심리극 진행","steps":["준비","시연","나누기"]}],"13":[{"t":"table","title":"게슈탈트 접촉 방해","head":["방해","관찰되는 집단원"],"rows":[["반전","타인에게 표출하기 어려워 거의 감정을 표현하지 않는 집단원에게 쉽게 관찰된다."],["투사","집단상담자나 다른 집단원이 압박을 하고 있다고 주장하는 집단원에게 관찰된다."],["편향","유머의 남발, 진술이 아닌 질문을 많이 사용하는 집단원에게 쉽게 관찰된다."],["내사","집단초기에 집단상담자의 개입이나 역할에 관한 의문을 갖지 않거나 · 질문을 거의 하지 않는 집단원에게 관찰된다."]]}],"14":[{"t":"tree","title":"교류분석 집단상담","root":"교류분석 집단상담","branches":[["계약","집단원과 집단상담자는 계약적 합의 하에 동등한 지위를 갖는다. · 집단에서 이루어야 할 목표를 구체적으로 진술한 계약을 맺는다."],["조력","스트로크에 의한 삶의 각본과 초기 결정을 발견하도록 조력한다. · 집단원이 연출한 게임으로 인해 부정적 감정이 만성화되는 과정을 발견하도록 돕는다. · 집단원들이 인생태도와 라켓을 탐색하고 효과적인 관계방식을 실험하도록 한다."],["효과","인간은 스스로 노력하면 변화할 수 있다는 희망을 제시한다. · 인간관계에 대한 이해를 통해 의사소통 문제를 해결하는데 도움이 된다. · 교육적ㆍ예방적ㆍ치료적 상담이 가능하다."]]},{"t":"table","title":"교류분석 용어","head":["용어","내용"],"rows":[["구조분석","세 가지 자아상태를 검토하도록 돕는 과정이다."],["게임","숨겨져 있지만 이득을 얻도록 계획된 이면적 교류의 연속이다."],["삶의 자세","긍정적인 삶의 자세 한 가지와 부정적인 삶의 자세 세 가지가 있다."],["시간의 구조화","개인이 시간을 구조화하는 여섯 가지 방법은 철회, 의례적 행동, 활동, 여흥, 게임, 친밀성이 있다."]]}],"15":[{"t":"tree","title":"인지행동 집단상담","root":"행동주의·인지행동 집단상담","branches":[["치료적 관계","상호협력과 적극적인 참여를 강조하는 치료적 관계가 필수적이다."],["협력적 경험주의","집단원들이 가설을 만들고 그것을 검증하게 하는 협력적 경험주의 방식을 취한다."],["증거","집단원들이 자동적 사고와 핵심 신념을 지지하거나 반박할 수 있는 증거를 찾아보도록 한다."],["안내된 발견","안내된 발견(guided discovery)을 통해 집단원이 생각하고 느끼며 행동하는 방식의 관련성을 알게 한다."]]},{"t":"tree","title":"행동 목표","root":"목표","branches":[["설정","집단상담자와 집단원이 동의하여 설정한다."],["관찰","측정가능하고 객관적 관찰이 가능해야 한다."],["개입","개개인의 문제에 대해 목표를 세우고 개별적인 개입이 이루어진다."],["대체","부적응 행동을 건설적이고 생산적인 행동으로 대체하는 것이다."]]},{"t":"table","title":"인지행동 기법","head":["기법","내용"],"rows":[["진술방식","“～ 해야만 한다.” 대신에 “～ 하면 더 낫다.”는 진술방식을 학습하게 한다."],["최악의 상황 상상","최악의 상황을 상상하게 하여 상황과 맞지 않는 부적절한 감정이 적절한 감정으로 변화될 수 있도록 한다."],["수치심 공격","창피하거나 부끄럽게 느껴지는 행동을 하게 함으로써 비난에 과도하게 영향을 받지 않도록 한다."],["역할연기","역할연기를 통해 집단원 자신이 할 수 있는 행동을 인식하게 한다."]]}],"16":[{"t":"tree","title":"현실치료 집단상담","root":"현실치료 집단상담","branches":[["태도","집단원을 무비판적이고 수용적인 태도로 상담한다."],["변화","집단원의 생각하기와 행동하기를 변화시키려고 노력한다."],["책임","집단원의 변명을 수용하지 않으며, 선택한 행동에 대해 책임을 지도록 한다."],["기법","질문하기, 직면하기, 역설적 기법, 유머 사용하기 등을 상담기법으로 사용할 수 있다."]]}],"17":[{"t":"tree","title":"실존주의 집단상담","root":"실존주의 집단상담","branches":[["자유","자신이 자기 삶의 주인이어야 한다는 자유를 인식하고 수용한다."],["주제","관계, 의미 찾기, 불안, 고통, 죽음과 같은 주제를 다룬다."],["강조","치료 기법보다 집단원의 현재 경험을 이해하는 것을 강조한다."],["목적","핵심 목적은 실존적 근심을 나눔으로써 자신을 발견하는 것이다."]]}],"19":[{"t":"vs","title":"청소년 집단상담","cols":[{"name":"이점","items":["다른 친구들도 나와 비슷한 감정과 생각을 갖고 있음을 알게 된다.","자기중심적인 사고나 태도의 변화를 가져올 수 있다.","자신의 고민을 드러내 해결해가면서 전보다 더 큰 자신감을 얻는다.","또래와의 상호작용을 통해 부정적인 감정을 다루는 방법을 연습할 수 있다."]},{"name":"청소년의 특성","items":["학교나 부모에 의해 참여하게 되는 경우 집단에 대한 관심이 없을 수도 있다.","교사나 부모와 같은 기성세대에게는 반항적인 태도를 가지고 도전할 수 있다.","신체적ㆍ생리적 변화로 외모에 관심을 갖게 된다.","자아중심적이고, 자기의식적인 특성을 보인다."]}]}],"20":[{"t":"tree","title":"집단상담 프로그램 계획","root":"집단상담 프로그램 계획","branches":[["전체 계획","전체 집단회기에 대한 전반적인 계획을 수립하고 시작한다. · 집단의 목표와 활동, 일정 등을 포함한 집단계획서를 미리 작성한다."],["집단 구성","집단원이 어릴수록 집단 크기를 적게 구성하도록 계획한다. · 이질적인 집단원의 포함 여부는 집단의 목표에 따라 달라질 수 있다. · 집단원의 발달단계와 발달과업을 고려하여 집단상담을 계획한다."],["법률·학교","미성년자의 집단상담 참여와 관련된 법률을 숙지한다. · 집단상담이 운영되는 학교의 상황과 방침을 고려한다. · 학교관계자, 교사, 보호자 및 법정대리인에게 집단상담의 이점을 설명한다."]]},{"t":"tree","title":"집단상담 운영","root":"운영","branches":[["참여할 권리","집단상담에 참여하지 않을 권리를 인정해준다."],["매체","청소년의 흥미를 불러일으킬 수 있는 매체를 적극 활용한다."],["감정표현","부정적인 감정표현을 건설적이고 생산적인 방향으로 이끌도록 돕는다."],["질문","집단상담자에게 사적이거나 짓궂은 질문을 할 경우 · 이에 대한 탐색질문을 한다."]]}]};
